(2066, 297, '_sections', 'field_6745586b42732'),
(2067, 18, 'sections_0_introduction', '<h2>Une attention particulière à chaque détail et une\r\npromesse de résultats probants</h2>'),
(2068, 18, '_sections_0_introduction', 'field_67455855cf587'),
(2069, 18, 'sections_0_colonnes_0_centre', '1'),
(2070, 18, '_sections_0_colonnes_0_centre', 'field_67455855dad1f'),
(2071, 18, 'sections_0_colonnes_0_image', '250'),
(2072, 18, '_sections_0_colonnes_0_image', 'field_67455855de9aa'),
(2073, 18, 'sections_0_colonnes_0_contenu', '<h5>Une stratégie sur-mesure</h5>\r\nChaque projet de vente est unique. Nous adaptons notre stratégie de vente pour maximiser les chances de succès tout en répondant à vos attentes spécifiques.'),
(2074, 18, '_sections_0_colonnes_0_contenu', 'field_67455855e25cb'),
(2075, 18, 'sections_0_colonnes_1_centre', '1'),
(2076, 18, '_sections_0_colonnes_1_centre', 'field_67455855dad1f'),
(2077, 18, 'sections_0_colonnes_1_image', '251'),
(2078, 18, '_sections_0_colonnes_1_image', 'field_67455855de9aa'),
(2079, 18, 'sections_0_colonnes_1_contenu', '<h5>La valorisation de votre bien</h5>\r\nNous offrons des estimations justes, sans céder à des baisses de prix par facilité. Grâce à des photos et vidéos de qualité, nous réalisons une promotion ciblée qui valorise votre propriété et met en lumière ses atouts exceptionnels.'),
(2080, 18, '_sections_0_colonnes_1_contenu', 'field_67455855e25cb'),
